it("skips the parent-area request entirely on an areaCache hit", async () => {
  const fetchMock = vi
    .fn()
    .mockResolvedValueOnce(okJson({ artists: [NIRVANA] }))
    .mockResolvedValueOnce(okJson([ABERDEEN_WA_HIT]));
