input.content:
import { lookupArtistLocation } from "/Users/bert/github/sound-map/shared/geocode.js";

// Stand-in for the Redis-backed areaCache api/geocode.js supplies, with
// counters so we can see the hit rate and the MusicBrainz calls it saves.
const store = new Map();
let hits = 0;
let misses = 0;
const areaCache = {
  get: async (id) => {
    const v = store.get(id);
    if (v === undefined) {
      misses++;
      return null;
    }
    hits++;
    return v;
  },
  set: async (id, parent) => void store.set(id, parent),
};

let mbCalls = 0;
const realFetch = globalThis.fetch;
globalThis.fetch = (url, init) => {
  if (String(url).includes("musicbrainz.org")) mbCalls++;
  return realFetch(url, init);
};

// London and Montréal repeat, which is exactly the collision the cache exists
// to exploit.
const artists = [
  "Burial",
  "Stereolab",
  "Sault",
  "Arcade Fire",
  "Godspeed You! Black Emperor",
  "Nirvana",
];

for (const name of artists) {
  const before = mbCalls;
  const result = await lookupArtistLocation(name, { areaCache });
  console.log(
    `${name.padEnd(30)} ${String(mbCalls - before)} MB call(s)  ${result?.placeName ?? "unresolved"}`,
  );
  await new Promise((r) => setTimeout(r, 2500));
}

console.log(
  `\narea cache: ${hits} hits / ${misses} misses` +
    `\nMusicBrainz calls: ${mbCalls} (would be ${artists.length * 2} with no area cache)`,
);

